'use server';

import { createClient as createSupabaseJsClient } from '@supabase/supabase-js';
import { sendEmail } from '@/lib/email';
import { AdminProfile } from '@/types/database';

export interface GenerateAdminLoginLinkResult {
  success: boolean;
  link?: string;
  error?: string;
}

export interface GetActiveInstitutionsResult {
  success: boolean;
  data?: AdminProfile[];
  error?: string;
}

export interface SendMagicLinkEmailResult {
  success: boolean;
  message?: string;
  error?: string;
}

/**
 * Normalizes an action link generated by Supabase:
 * Replaces localhost base URL and query parameters with process.env.NEXT_PUBLIC_APP_URL.
 */
function normalizeActionLink(rawLink: string): string {
  const targetAppUrl = (
    process.env.NEXT_PUBLIC_APP_URL ||
    process.env.NEXT_PUBLIC_SITE_URL ||
    ''
  ).trim().replace(/\/+$/, '');

  if (!targetAppUrl) return rawLink;

  let link = rawLink;

  // Replace localhost origin in the link
  link = link.replace(/^http:\/\/(localhost|127\.0\.0\.1)(:\d+)?/, targetAppUrl);

  // Replace localhost inside query params (both raw and URL-encoded)
  link = link.replaceAll('http://localhost:3000', targetAppUrl);
  link = link.replaceAll('http%3A%2F%2Flocalhost%3A3000', encodeURIComponent(targetAppUrl));

  return link;
}

/**
 * Server Action: Fetches all active & inactive school admin profiles directly
 * using SUPABASE_SERVICE_ROLE_KEY to bypass Row Level Security (RLS).
 */
export async function getActiveInstitutions(): Promise<GetActiveInstitutionsResult> {
  try {
    const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
    const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY?.trim();

    if (!supabaseUrl || !serviceRoleKey) {
      console.warn(
        '[getActiveInstitutions] SUPABASE_SERVICE_ROLE_KEY not configured. Returning empty or fallback list.'
      );
      return { success: true, data: [] };
    }

    const supabaseAdmin = createSupabaseJsClient(supabaseUrl, serviceRoleKey, {
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
    });

    const { data, error } = await supabaseAdmin
      .from('admin_profiles')
      .select('*')
      .order('created_at', { ascending: false });

    if (error) {
      console.error('[getActiveInstitutions] DB Error:', error);
      return { success: false, error: error.message };
    }

    return { success: true, data: (data || []) as AdminProfile[] };
  } catch (err: any) {
    console.error('[getActiveInstitutions] Unexpected error:', err);
    return {
      success: false,
      error: err?.message || 'שגיאה פנימית בטעינת רשימת המוסדות',
    };
  }
}

/**
 * Server Action: Toggles an institution's active/frozen status directly
 * using SUPABASE_SERVICE_ROLE_KEY to bypass RLS.
 */
export async function toggleInstitutionActive(
  profileId: string,
  isActive: boolean
): Promise<{ success: boolean; error?: string }> {
  try {
    const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
    const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY?.trim();

    if (!supabaseUrl || !serviceRoleKey) {
      return { success: true };
    }

    const supabaseAdmin = createSupabaseJsClient(supabaseUrl, serviceRoleKey, {
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
    });

    const { error } = await supabaseAdmin
      .from('admin_profiles')
      .update({ is_active: isActive })
      .eq('id', profileId);

    if (error) {
      console.error('[toggleInstitutionActive] Error updating status:', error);
      return { success: false, error: error.message };
    }

    return { success: true };
  } catch (err: any) {
    console.error('[toggleInstitutionActive] Unexpected error:', err);
    return {
      success: false,
      error: err?.message || 'שגיאה בעדכון סטטוס מוסד',
    };
  }
}

/**
 * Server Action: Generates an action link (Magic Link) for a school admin using Supabase Admin API.
 * Uses SUPABASE_SERVICE_ROLE_KEY to bypass email rate limits.
 * Automatically replaces localhost URLs with process.env.NEXT_PUBLIC_APP_URL.
 */
export async function generateAdminLoginLink(
  email: string,
  originUrl?: string
): Promise<GenerateAdminLoginLinkResult> {
  try {
    const cleanEmail = email?.trim().toLowerCase();
    if (!cleanEmail) {
      return { success: false, error: 'כתובת דוא״ל לא סופקה' };
    }

    const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
    const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY?.trim();

    const appBaseUrl = (
      process.env.NEXT_PUBLIC_APP_URL ||
      process.env.NEXT_PUBLIC_SITE_URL ||
      originUrl ||
      'http://localhost:3000'
    ).trim().replace(/\/+$/, '');

    if (!supabaseUrl || !serviceRoleKey) {
      console.warn(
        '[generateAdminLoginLink] SUPABASE_SERVICE_ROLE_KEY not configured. Falling back to local/demo link.'
      );
      return {
        success: true,
        link: `${appBaseUrl}/admin/login?email=${encodeURIComponent(cleanEmail)}&demo=true`,
      };
    }

    const supabaseAdmin = createSupabaseJsClient(supabaseUrl, serviceRoleKey, {
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
    });

    const redirectTo = `${appBaseUrl}/auth/callback?next=/admin`;

    const { data, error } = await supabaseAdmin.auth.admin.generateLink({
      type: 'magiclink',
      email: cleanEmail,
      options: {
        redirectTo,
      },
    });

    if (error) {
      console.error('[generateAdminLoginLink] Supabase generateLink error:', error);
      return { success: false, error: error.message };
    }

    const rawActionLink = data?.properties?.action_link;
    if (!rawActionLink) {
      return {
        success: false,
        error: 'לא התקבל קישור התחברות מסופאבייס',
      };
    }

    // TASK 3: Normalize action link and replace localhost with NEXT_PUBLIC_APP_URL
    const normalizedLink = normalizeActionLink(rawActionLink);

    return {
      success: true,
      link: normalizedLink,
    };
  } catch (err: any) {
    console.error('[generateAdminLoginLink] Unexpected error:', err);
    return {
      success: false,
      error: err?.message || 'שגיאה פנימית ביצירת קישור התחברות',
    };
  }
}

/**
 * Server Action: Sends a Magic Link login email to an admin using Nodemailer.
 */
export async function sendMagicLinkEmail(
  email: string,
  actionLink: string,
  schoolName?: string
): Promise<SendMagicLinkEmailResult> {
  try {
    const cleanEmail = email?.trim().toLowerCase();
    if (!cleanEmail) {
      return { success: false, error: 'כתובת דוא״ל לא סופקה' };
    }

    const normalizedLink = normalizeActionLink(actionLink);

    const schoolLabel = schoolName ? ` - ${schoolName}` : '';
    const subject = `קישור התחברות למערכת דיווח שעות פרטניות${schoolLabel}`;

    const html = `
<!DOCTYPE html>
<html lang="he" dir="rtl">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>קישור התחברות למערכת שעות פרטניות</title>
</head>
<body dir="rtl" style="margin:0;padding:0;background-color:#f8fafc;font-family:'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;text-align:right;">
  <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" dir="rtl" style="background-color:#f8fafc;padding:32px 16px;">
    <tr>
      <td align="center">
        <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" dir="rtl" style="max-width:560px;background-color:#ffffff;border-radius:20px;border:1px solid #e2e8f0;overflow:hidden;box-shadow:0 10px 25px -5px rgba(0,0,0,0.05);">
          <!-- Header Banner -->
          <tr>
            <td style="background:linear-gradient(135deg, #4f46e5 0%, #0284c7 100%);padding:28px 32px;color:#ffffff;">
              <h1 style="margin:0;font-size:22px;font-weight:700;">מערכת ניהול שעות פרטניות</h1>
              <p style="margin:6px 0 0;font-size:13px;opacity:0.9;">קישור התחברות ישיר ומאובטח (Magic Link)</p>
            </td>
          </tr>
          <!-- Body Content -->
          <tr>
            <td style="padding:32px;">
              <p style="font-size:15px;line-height:1.6;color:#334155;margin:0 0 16px;">
                שלום רב,
              </p>
              <p style="font-size:14px;line-height:1.6;color:#475569;margin:0 0 24px;">
                הופק עבורך קישור התחברות ישיר ומאובטח לממשק ניהול בית הספר${schoolName ? ` (${schoolName})` : ''}.
                לחיצה על הכפתור מטה תחבר אותך ישירות למערכת ללא צורך בהזנת סיסמה:
              </p>

              <!-- CTA Button -->
              <div style="text-align:center;margin:32px 0;">
                <a href="${normalizedLink}" style="display:inline-block;background-color:#4f46e5;color:#ffffff;text-decoration:none;font-weight:700;font-size:15px;padding:14px 32px;border-radius:12px;box-shadow:0 4px 12px rgba(79,70,229,0.3);">
                  כניסה ישירה למערכת
                </a>
              </div>

              <!-- Fallback Link URL -->
              <div style="background-color:#f8fafc;border-radius:12px;border:1px solid #e2e8f0;padding:16px;margin:24px 0;">
                <p style="margin:0 0 8px;font-size:12px;color:#64748b;font-weight:600;">
                  אם הכפתור אינו פועל, ניתן להעתיק את הקישור הבא לדפדפן:
                </p>
                <p style="margin:0;font-size:11px;font-family:monospace;word-break:break-all;color:#4f46e5;" dir="ltr">
                  ${normalizedLink}
                </p>
              </div>

              <p style="font-size:12px;color:#94a3b8;line-height:1.5;margin:24px 0 0;border-top:1px solid #f1f5f9;padding-top:16px;">
                קישור זה הינו אישי ומאובטח. אין להעביר אותו לגורמים שאינם מורשים.
              </p>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>
    `.trim();

    const emailRes = await sendEmail({
      to: cleanEmail,
      subject,
      html,
    });

    if (!emailRes.success) {
      return {
        success: false,
        error: emailRes.error || 'שגיאה בשליחת הדוא״ל',
      };
    }

    return {
      success: true,
      message: `אימייל עם קישור התחברות נשלח בהצלחה אל ${cleanEmail}`,
    };
  } catch (err: any) {
    console.error('[sendMagicLinkEmail] Unexpected error:', err);
    return {
      success: false,
      error: err?.message || 'שגיאה בלתי צפויה בשליחת הדוא״ל',
    };
  }
}
